(function(){
  'use strict';
  const el=id=>document.getElementById(id);let client=null,mode='login',busy=false,loaded=false,expiryTimer=null,user=null;
  function message(text,kind=''){el('auth-status').textContent=text;el('auth-status').className='auth-status '+kind;el('auth-status').hidden=!text}
  function setBusy(value){busy=value;el('auth-submit').disabled=value||!client;el('auth-switch').disabled=value;el('auth-submit').textContent=value?'Aguarde…':mode==='login'?'Entrar na central':'Criar conta'}
  function setMode(next){mode=next;el('auth-title').textContent=mode==='login'?'Entrar na central':'Criar sua conta';el('auth-description').textContent=mode==='login'?'Use seu e-mail e senha para acessar a operação.':'Cadastre-se com e-mail e senha. O acesso à central depende da liberação do gestor.';el('auth-name-label').hidden=mode==='login';el('auth-name').required=mode!=='login';el('auth-password').autocomplete=mode==='login'?'current-password':'new-password';el('auth-password').minLength=mode==='login'?1:8;el('auth-switch').textContent=mode==='login'?'Ainda não tenho conta':'Já tenho conta';message('');setBusy(false)}
  function script(src){return new Promise((resolve,reject)=>{const tag=document.createElement('script');tag.src=src;tag.onload=resolve;tag.onerror=()=>reject(Error('Não foi possível carregar a central. Atualize a página.'));document.body.append(tag)})}
  function authorized(rows){return Array.isArray(rows)&&rows.some(r=>r.ativo===true&&r.cidade_id===window.UP_CONFIG.cityId&&['master','gestor','central'].includes(r.papel))}
  async function enter(currentUser){user=currentUser;const access=await client.getAccess();if(el('platform-admin-link'))el('platform-admin-link').hidden=!access.some(r=>r.super_admin===true);if(!authorized(access)){el('auth-form').hidden=true;el('auth-switch').hidden=true;el('auth-pending').hidden=false;el('pending-email').textContent=currentUser.email||'';message('Conta autenticada. Aguardando liberação para a central de Pitangueiras.','success');return false}
    window.UP_STATE_KEY='vuppi-delivery-demo-v3:'+client.projectUrl+':'+currentUser.id;
    if(!loaded){await script('base.js');await script('central.js');loaded=true;}
    el('operator-email').textContent=currentUser.email||'Operador';el('auth-shell').hidden=true;document.querySelector('.layout').hidden=false;document.querySelector('.demo').innerHTML='<strong>Login conectado</strong><span>Conta autenticada pelo Supabase. Corridas, entregas e tarifas ainda são uma demonstração local, separada por usuário.</span>';
    scheduleCheck();return true;
  }
  function lock(){document.querySelector('.layout').hidden=true;document.querySelectorAll('dialog[open]').forEach(d=>d.close());el('auth-shell').hidden=false;clearTimeout(expiryTimer)}
  function scheduleCheck(){clearTimeout(expiryTimer);expiryTimer=setTimeout(async()=>{try{await client.getUser();const access=await client.getAccess();if(!authorized(access)){lock();message('Seu acesso à central foi revogado. Entre em contato com o gestor.','error');return}scheduleCheck()}catch(e){lock();message(e.message,'error');el('auth-form').hidden=false;el('auth-switch').hidden=false;setBusy(false)}},60000)}
  async function signout(){lock();el('auth-form').hidden=true;el('auth-pending').hidden=true;message('Saindo da conta…');try{if(client)await client.signOut();location.reload()}catch{el('auth-pending').hidden=false;message('Não foi possível encerrar a sessão no servidor. Reconecte e clique em Sair novamente.','error')}}
  el('auth-switch').onclick=()=>setMode(mode==='login'?'signup':'login');el('password-toggle').onclick=()=>{const show=el('auth-password').type==='password';el('auth-password').type=show?'text':'password';el('password-toggle').textContent=show?'Ocultar':'Mostrar';el('password-toggle').setAttribute('aria-pressed',String(show))};
  el('auth-form').onsubmit=async e=>{e.preventDefault();if(busy||!client)return;setBusy(true);message('');try{const email=el('auth-email').value.trim(),password=el('auth-password').value;const current=mode==='login'?await client.signIn(email,password):await client.signUp(el('auth-name').value.trim(),email,password);el('auth-password').value='';await enter(current)}catch(error){message(error.message,'error')}finally{setBusy(false)}};
  el('pending-check').onclick=async()=>{el('pending-check').disabled=true;try{await enter(await client.getUser())}catch(error){message(error.message,'error')}finally{el('pending-check').disabled=false}};
  ['logout','logout-mobile','pending-logout'].forEach(id=>el(id).onclick=signout);
  async function start(){try{if(!['https:','http:'].includes(location.protocol)){message('Você abriu apenas o arquivo da tela. Para criar conta, execute INICIAR-UP.cmd na pasta da plataforma e abra http://localhost:8787 no navegador. O endereço publicado também permite o cadastro quando estiver disponível.');setBusy(false);return}client=window.UPAuthClient.create(window.UP_CONFIG);setBusy(true);message('Verificando conexão…');const status=await client.status();if(!status.ready){client=null;message('A configuração segura do servidor ainda está em preparação.');return}const current=await client.restore();if(current)await enter(current);else message('')}catch(error){client=null;message(error.message,'error')}finally{setBusy(false)}}
  start();
})();
